import {isValidElement, useMemo} from 'react'
import {isValidElementType} from 'react-is'
import {styled} from 'styled-components'

import {ThemeFontWeightKey} from '../../../theme/system/font'
import {_getArrayProp} from '../../styles/helpers'
import {responsiveRadiusStyle} from '../../styles/radius/radiusStyle'
import {ResponsiveRadiusStyleProps} from '../../styles/radius/types'
import {useTheme_v2} from '../../theme/useTheme'
import {ButtonMode, ButtonTextAlign, ButtonTone, ButtonWidth} from '../../types/button'
import {ElementType, Props} from '../../types/component'
import {FlexJustify} from '../../types/flex'
import {Box} from '../box/box'
import {Flex} from '../flex/flex'
import {Spinner} from '../spinner/spinner'
import {Text} from '../text/text'
import {ResponsivePaddingProps, ResponsiveRadiusProps} from '../types'
import {buttonBaseStyles, buttonColorStyles} from './styles'

import {buttonLoadingBox} from './button.css'

/**
 * @public
 */
export interface ButtonOwnProps extends ResponsivePaddingProps, ResponsiveRadiusProps {
  fontSize?: number | number[]
  mode?: ButtonMode
  // oxlint-disable-next-line no-redundant-type-constituents
  icon?: React.ElementType | React.ReactNode
  // oxlint-disable-next-line no-redundant-type-constituents
  iconRight?: React.ElementType | React.ReactNode
  justify?: FlexJustify | FlexJustify[]
  /**
   * @beta Do not use in production, as this might change.
   */
  loading?: boolean
  selected?: boolean
  /**
   * @deprecated Use `gap` instead.
   */
  space?: never
  gap?: number | number[]
  muted?: boolean
  text?: React.ReactNode
  textAlign?: ButtonTextAlign
  textWeight?: ThemeFontWeightKey
  tone?: ButtonTone
  type?: 'button' | 'reset' | 'submit'
  width?: ButtonWidth
}

/**
 * @public
 */
export type ButtonProps<E extends ElementType = 'button'> = Props<ButtonOwnProps, E>

const StyledButton = styled.button<
  {$mode: ButtonMode; $tone: ButtonTone; $width?: ButtonWidth} & ResponsiveRadiusStyleProps
>(responsiveRadiusStyle, buttonBaseStyles, buttonColorStyles)

function ButtonComponent(
  props: ButtonOwnProps & {as?: ElementType} & Omit<
      React.HTMLProps<HTMLButtonElement>,
      'as' | 'width'
    >,
) {
  const {
    children,
    disabled,
    ref,
    fontSize = 1,
    icon: IconComponent,
    iconRight: IconRightComponent,
    justify: justifyProp = 'center',
    loading,
    mode = 'default',
    padding: paddingProp = 3,
    paddingX: paddingXProp,
    paddingY: paddingYProp,
    paddingTop: paddingTopProp,
    paddingBottom: paddingBottomProp,
    paddingLeft: paddingLeftProp,
    paddingRight: paddingRightProp,
    radius: radiusProp = 2,
    selected,
    gap = 3,
    text,
    textAlign,
    textWeight,
    tone = 'default',
    type = 'button',
    muted = false,
    width,
    ...restProps
  } = props
  const {button} = useTheme_v2()

  const justify = _getArrayProp(justifyProp)
  const padding = _getArrayProp(paddingProp)
  const paddingX = _getArrayProp(paddingXProp)
  const paddingY = _getArrayProp(paddingYProp)
  const paddingTop = _getArrayProp(paddingTopProp)
  const paddingBottom = _getArrayProp(paddingBottomProp)
  const paddingLeft = _getArrayProp(paddingLeftProp)
  const paddingRight = _getArrayProp(paddingRightProp)
  const radius = _getArrayProp(radiusProp)
  const spacing = _getArrayProp(gap)

  const boxProps = useMemo(
    () => ({
      // flex: 1,
      padding,
      paddingX,
      paddingY,
      paddingTop,
      paddingBottom,
      paddingLeft,
      paddingRight,
    }),
    [padding, paddingX, paddingY, paddingTop, paddingBottom, paddingLeft, paddingRight],
  )

  return (
    <StyledButton
      data-ui="Button"
      {...restProps}
      $mode={mode}
      $radius={radius}
      $tone={tone}
      data-disabled={Boolean(loading || disabled)}
      data-selected={selected ? '' : undefined}
      disabled={Boolean(loading || disabled)}
      ref={ref}
      type={type}
      $width={width}
    >
      {Boolean(loading) && (
        <div className={buttonLoadingBox} data-ui="ButtonLoading">
          <Spinner />
        </div>
      )}

      {(IconComponent || text || IconRightComponent) && (
        <Box as="span" {...boxProps}>
          <Flex as="span" justify={justify} gap={spacing}>
            {IconComponent && (
              <Text size={fontSize}>
                {isValidElement(IconComponent) && IconComponent}
                {isValidElementType(IconComponent) && <IconComponent />}
              </Text>
            )}

            {text && (
              <Box>
                <Text
                  muted={muted}
                  align={textAlign}
                  size={fontSize}
                  textOverflow="ellipsis"
                  weight={textWeight ?? button.textWeight}
                >
                  {text}
                </Text>
              </Box>
            )}

            {IconRightComponent && (
              <Text size={fontSize}>
                {isValidElement(IconRightComponent) && IconRightComponent}
                {isValidElementType(IconRightComponent) && <IconRightComponent />}
              </Text>
            )}
          </Flex>
        </Box>
      )}

      {children && (
        <Box as="span" {...boxProps}>
          {children}
        </Box>
      )}
    </StyledButton>
  )
}

/**
 * @public
 */
export const Button: <E extends ElementType = 'button'>(
  props: ButtonProps<E>,
) => React.JSX.Element = ButtonComponent
